self.KB_CONTENT["card:753294"]={"id":"card:753294","ty":"card","sourceId":"753294","title":"『單據指定不控管信用額度作業』中的『選擇類型』為何？","ver":"iGP","topic":"銷貨單","keywords":["銷貨單","變更單","訂單","出貨"],"y":"other","answer":"* 不可空白。* 分為1.訂單、2.訂單變更單、3.銷貨單、4.出貨通知單及5.暫出單。* 修改時清除選擇單據資料。","links":[],"pdfText":"","pdfPages":0,"pdfChars":0,"merged":[],"file":"kb-cards.jsonl"};
