self.KB_CONTENT["card:785046"]={"id":"card:785046","ty":"card","sourceId":"785046","title":"『資產盤點資料產生作業』中的『選擇資產編號』為何？","ver":"GP4以上","topic":"資產","keywords":["資產","編號","盤點","固定"],"y":"other","answer":"* 可勾選是否區間選擇。可自行選擇離散或區間。* 可選擇(icon)或[F2]資產資料查詢固定資產編號之區間。若空白表全部資產編號皆納入。","links":[],"pdfText":"","pdfPages":0,"pdfChars":0,"merged":[],"file":"kb-cards.jsonl"};
