self.KB_CONTENT["card:755111"]={"id":"card:755111","ty":"card","sourceId":"755111","title":"『合約訂單建立作業』中的『總數量 (TW035)』為何？","ver":"iGP","topic":"單身","keywords":["單身","訂單","單位","合約"],"y":"other","answer":"* 為單身數量累計(1).數量表達方式「單一單位」時，加總單身數量+贈品數量。(2).數量表達方式「雙單位」時，加總單身數量+贈品數量的整數部份。","links":[],"pdfText":"","pdfPages":0,"pdfChars":0,"merged":[],"file":"kb-cards.jsonl"};
